examples.template:
MonarchButton({{trigger}}, systemImage: "person.badge.plus", variant: .primary) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text({{description}}).monarchTextStyle(.body)
                    if !failed.isEmpty {
                        MonarchBanner("Some invitations were not sent", message: failed.joined(separator: "\n"), tone: .warning)
                    }
                    MonarchTagInput(
                        {{emails.label}},
                        tags: $emails,
                        isRequired: true,
                        prompt: {{emails.placeholder}},
                        helper: {{emails.helper}},
                        separators: [",", " ", "\n"],
                        maxCount: 20,
                        validate: { value, _ in value.contains("@") ? nil : "“\(value)” is not an email address." }
                    )
                    .monarchHelperAbove()
                    MonarchRolePicker(
                        {{role.label}},
                        selection: $role,
                        roles: [
                            MonarchRoleOption({{role.options.0.value}}, title: {{role.options.0.label}}, description: {{role.options.0.description}}),
                            MonarchRoleOption({{role.options.1.value}}, title: {{role.options.1.label}}, description: {{role.options.1.description}}),
                            MonarchRoleOption({{role.options.2.value}}, title: {{role.options.2.label}}, description: {{role.options.2.description}}),
                        ],
                        isRequired: true,
                        showsDescription: false,
                        layout: .compact
                    )
                    MonarchAppAccessPicker(
                        [
                            MonarchAppAccessOption(id: {{apps.options.0.id}}, name: {{apps.options.0.name}}, description: {{apps.options.0.description}}),
                            MonarchAppAccessOption(id: {{apps.options.1.id}}, name: {{apps.options.1.name}}, description: {{apps.options.1.description}}),
                            MonarchAppAccessOption(id: {{apps.options.2.id}}, name: {{apps.options.2.name}}, description: {{apps.options.2.description}}),
                        ],
                        selection: $apps,
                        label: {{apps.label}}
                    )
                    MonarchTextField({{note.label}}, text: $note, prompt: {{note.placeholder}}, optionalText: {{note.helper}}, axis: .vertical, lineLimit: 3...6)
                }
                .padding(theme.spacing.space4)
            }
            .navigationTitle({{title}})
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button({{cancel}}) { isOpen = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(emails.count > 1 ? "Send \(emails.count) invites" : {{send}}) { send() }
                        .disabled(emails.isEmpty || role == nil || isSending)
                }
            }
        }
        .interactiveDismissDisabled(isSending)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var emails: [String] = []
@State private var role: String? = {{role.value}}
@State private var apps: Set<String> = []
@State private var note = ""
@State private var isSending = false
@State private var failed: [String] = []

private func send() {
    isSending = true
    Task {
        // Send the invitations here; keep the addresses that failed.
        try? await Task.sleep(for: .milliseconds(300))
        failed = []
        isSending = false
        isOpen = false
        AccessibilityNotification.Announcement("Invited \(emails.count) people").post()
    }
}

