examples.code:
MonarchButton("Invite people", systemImage: "person.badge.plus", variant: .primary) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text("They’ll get an email and join once they accept the invitation.").monarchTextStyle(.body)
                    if !failed.isEmpty {
                        MonarchBanner("Some invitations were not sent", message: failed.joined(separator: "\n"), tone: .warning)
                    }
                    MonarchTagInput(
                        "Email addresses",
                        tags: $emails,
                        isRequired: true,
                        prompt: "name@example.com",
                        helper: "Separate several addresses with commas, spaces or new lines.",
                        separators: [",", " ", "\n"],
                        maxCount: 20,
                        validate: { value, _ in value.contains("@") ? nil : "“\(value)” is not an email address." }
                    )
                    .monarchHelperAbove()
                    MonarchRolePicker(
                        "Role",
                        selection: $role,
                        roles: [
                            MonarchRoleOption("viewer", title: "Viewer", description: "Can see everything but change nothing."),
                            MonarchRoleOption("member", title: "Member", description: "Can create and edit work."),
                            MonarchRoleOption("admin", title: "Admin", description: "Can also manage members and settings."),
                        ],
                        isRequired: true,
                        showsDescription: false,
                        layout: .compact
                    )
                    MonarchAppAccessPicker(
                        [
                            MonarchAppAccessOption(id: "notes", name: "Notes", description: "Shared documents"),
                            MonarchAppAccessOption(id: "tasks", name: "Tasks", description: "Projects and issues"),
                            MonarchAppAccessOption(id: "calendar", name: "Calendar", description: "Shared calendars"),
                        ],
                        selection: $apps,
                        label: "App access"
                    )
                    MonarchTextField("Personal note", text: $note, prompt: "Add a note to the invitation email", optionalText: "Optional", axis: .vertical, lineLimit: 3...6)
                }
                .padding(theme.spacing.space4)
            }
            .navigationTitle("Invite people")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { isOpen = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(emails.count > 1 ? "Send \(emails.count) invites" : "Send invite") { send() }
                        .disabled(emails.isEmpty || role == nil || isSending)
                }
            }
        }
        .interactiveDismissDisabled(isSending)
    }
